UPDATE `world`.`quest_template` SET `AreaDescription` = 'We have much to discuss.', `QuestCompletionLog` = 'There are those that will disagree with my decision. But I will not have us lose our home. If we must host temporary guests, so be it.', `RewardBonusMoney` = 234000, `RewardNextQuest` = 86735 WHERE `ID` = 86734;
UPDATE `world`.`quest_objectives_locale` `l` JOIN `world`.`quest_objectives` `o` ON `o`.`ID` = `l`.`ID` SET `l`.`Description` = `o`.`Description` WHERE `l`.`QuestId` = 86734;
